/// Common generated framing boundary; implementation owns waiting and identity.
pub use abstraction_frame::FrameTransport;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ServiceError {
    pub code: String,
    pub message: String,
}

#[derive(Debug)]
pub enum CallError<E> {
    /// Transport failure does not establish whether the receiver accepted work.
    Transport(E),
    Refusal(Refusal),
    Dispatch(&'static str),
    Service(ServiceError),
}

fn service_decode<T>(data: &[u8], decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<T, Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth: 0 };
    r.skip_ws();
    let value = decode(&mut r)?;
    r.skip_ws();
    if r.pos != data.len() {
        return r.refuse("trailing_bytes");
    }
    Ok(value)
}

fn service_encode<T>(value: &T, check: fn(&T) -> Result<(), Refusal>, encode: fn(&mut Vec<u8>, &T, i32), decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<Vec<u8>, Refusal> {
    check(value)?;
    let mut data = Vec::new();
    encode(&mut data, value, 0);
    service_decode(&data, decode)?;
    Ok(data)
}

/// General exact-rule authorization decision point with a bounded, registrable
/// catalogue and persistence. Unknown, absent, unspecified, expired, failed and
/// refused decisions never permit. Explicitly authorized operator configuration
/// registers actions and grants/revokes exact rules; no serialized awake lease
/// is introduced.
pub trait Authorization {
    type Error;
    /// Evaluate the bound receiving account/program against an exact
    /// action/resource rule. This result is advisory to the caller; resource
    /// services query the decision point themselves.
    fn decide(&self, action: String, resource: String) -> Result<Decision, Self::Error>;
    /// Evaluate a subject assertion only when the receiving peer is explicitly
    /// authorized as an enforcement point for this action/resource. Same
    /// account alone grants no relay authority. The designated enforcer is
    /// trusted to supply its actual bound subject. Nil or refusing enforcer
    /// policy yields forbidden before policy lookup.
    fn decide_for(&self, subject: Subject, action: String, resource: String) -> Result<Decision, Self::Error>;
}

pub struct AuthorizationClient<T> {
    transport: T,
}

impl<T> AuthorizationClient<T> {
    pub fn new(transport: T) -> Self {
        Self { transport }
    }

    pub fn transport(&self) -> &T {
        &self.transport
    }
}

impl<T: FrameTransport> Authorization for AuthorizationClient<T> {
    type Error = CallError<T::Error>;
    fn decide(&self, action: String, resource: String) -> Result<Decision, Self::Error> {
        let args = OAAuthorizationDecideArguments { action, resource };
        let arguments = service_encode(&args, service_check_oa_authorization_decide_arguments, enc_oa_authorization_decide_arguments, decode_oa_authorization_decide_arguments).map_err(CallError::Refusal)?;
        let request = OAServiceFrame { version: 1, service: "abstraction.rights/authorization@1".into(), method: "Decide".into(), arguments };
        let frame = service_encode(&request, service_check_oa_service_frame, enc_oa_service_frame, decode_oa_service_frame).map_err(CallError::Refusal)?;
        let reply = self.transport.exchange_frame(&frame).map_err(CallError::Transport)?;
        let reply = service_decode(&reply, decode_oa_service_reply).map_err(CallError::Refusal)?;
        if reply.version != 1 {
            return Err(CallError::Dispatch("unknown_version"));
        }
        if reply.service != "abstraction.rights/authorization@1" || reply.method != "Decide" {
            return Err(CallError::Dispatch("mismatched_response"));
        }
        if !reply.ok {
            let error = service_decode(&reply.payload, decode_oa_service_error).map_err(CallError::Refusal)?;
            if error.code.is_empty() {
                return Err(CallError::Dispatch("invalid_error"));
            }
            return Err(CallError::Service(ServiceError { code: error.code, message: error.message }));
        }
        let result = service_decode(&reply.payload, decode_oa_authorization_decide_result).map_err(CallError::Refusal)?;
        Ok(result.value)
    }

    fn decide_for(&self, subject: Subject, action: String, resource: String) -> Result<Decision, Self::Error> {
        let args = OAAuthorizationDecideForArguments { subject, action, resource };
        let arguments = service_encode(&args, service_check_oa_authorization_decide_for_arguments, enc_oa_authorization_decide_for_arguments, decode_oa_authorization_decide_for_arguments).map_err(CallError::Refusal)?;
        let request = OAServiceFrame { version: 1, service: "abstraction.rights/authorization@1".into(), method: "DecideFor".into(), arguments };
        let frame = service_encode(&request, service_check_oa_service_frame, enc_oa_service_frame, decode_oa_service_frame).map_err(CallError::Refusal)?;
        let reply = self.transport.exchange_frame(&frame).map_err(CallError::Transport)?;
        let reply = service_decode(&reply, decode_oa_service_reply).map_err(CallError::Refusal)?;
        if reply.version != 1 {
            return Err(CallError::Dispatch("unknown_version"));
        }
        if reply.service != "abstraction.rights/authorization@1" || reply.method != "DecideFor" {
            return Err(CallError::Dispatch("mismatched_response"));
        }
        if !reply.ok {
            let error = service_decode(&reply.payload, decode_oa_service_error).map_err(CallError::Refusal)?;
            if error.code.is_empty() {
                return Err(CallError::Dispatch("invalid_error"));
            }
            return Err(CallError::Service(ServiceError { code: error.code, message: error.message }));
        }
        let result = service_decode(&reply.payload, decode_oa_authorization_decide_for_result).map_err(CallError::Refusal)?;
        Ok(result.value)
    }
}

/// Explicitly authorized administration of the configured decision policy:
/// catalogue registration and retirement, exact rules with expiry and
/// provenance. Receiving same-account Program proof plus a trusted typed-peer
/// operator callback is required; nil refuses. Policy denial is forbidden;
/// callback/storage failure is unavailable. No caller credential, verified flag
/// or provider path is accepted. Resource services remain the receiving
/// enforcement points. Legacy bearer and awake lease behavior is separate.
pub trait AuthorizationOperator {
    type Error;
    /// Read bounded current rules and catalogue under explicit operator
    /// authorization. Every continuation rechecks authorization; no enumeration
    /// session is retained for disconnected/slow callers.
    fn list_policy(&self, cursor: String, limit: i64) -> Result<PolicyPage, Self::Error>;
    /// Atomically compare the expected durable revision and set one exact
    /// permit/deny rule with no expiry and an empty reason. Revision is bounded
    /// to 128 UTF-8 bytes. Operator context and authority are checked again
    /// inside the atomic edit after lock waiting. The rule records the
    /// operator's established subject and the edit time. An unexpired rule with
    /// the same permit is a no-op that keeps its record. Uncatalogued actions
    /// and malformed targets are invalid; no resource permission is inferred
    /// from the operator request itself.
    fn set_rule(&self, expected_revision: String, rule: PolicyRule) -> Result<PolicyEdit, Self::Error>;
    /// Atomically remove one exact rule if the revision matches. The next fresh
    /// decision observes successful revocation. A failed/uncertain reply claims
    /// no successful revocation; inspect current state before another intent.
    /// It does not cancel an existing connection-owned awake lease.
    fn revoke_rule(&self, expected_revision: String, subject: Subject, action: String, resource: String) -> Result<PolicyEdit, Self::Error>;
    /// As SetRule, recording why and an expiry ttl_ms after the service's edit
    /// time. ttl_ms 0 sets no expiry; otherwise it is 1..31536000000. why is
    /// 0..256 UTF-8 bytes without control characters. A retained rule with the
    /// same permit, reason and expiry is a no-op; any other difference writes,
    /// including a new expiry.
    fn set_rule_for(&self, expected_revision: String, rule: PolicyRule, ttl_ms: i64, why: String) -> Result<PolicyEdit, Self::Error>;
    /// Read one exact rule with its provenance and expiry under operator
    /// authorization, rechecked after the read.
    fn read_rule(&self, subject: Subject, action: String, resource: String) -> Result<RuleRead, Self::Error>;
    /// Add an action named <owner>/<name> to the catalogue. owner is 1..64
    /// bytes and name 1..63 bytes of lowercase ASCII letters, digits, '.', '_'
    /// and '-', each beginning with a letter or digit. Registering an action
    /// already in the catalogue applies without writing. A registration records
    /// the operator's established subject and the service time. Registration
    /// grants nothing: decisions on the action read not_granted until a rule
    /// exists.
    fn register_action(&self, expected_revision: String, action: String) -> Result<ActionEdit, Self::Error>;
    /// Remove a registered action and every rule naming it. Retiring a seeded
    /// action is invalid. Retiring an action outside the catalogue is unknown.
    /// Decisions on a retired action read unknown_action.
    fn retire_action(&self, expected_revision: String, action: String) -> Result<ActionEdit, Self::Error>;
}

